import{_ as r,r as e,o as s,c,e as d,a as n,s as u}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"AJAX data-* атрибуты API (AJAX Data attributes API) - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"data-* атрибуты API","slug":"data-атрибуты-api","link":"#data-атрибуты-api","children":[]},{"level":2,"title":"Примеры","slug":"примеры","link":"#примеры","children":[]}],"relativePath":"1.x/ru/ajax/attributes-api.md","filePath":"1.x/ru/ajax/attributes-api.md"}'),l={name:"1.x/ru/ajax/attributes-api.md"};function p(i,t,q,g,h,m){const o=e("pre-heading"),a=e("post-heading");return s(),c("div",null,[d(o),t[0]||(t[0]=n("h1",null,"AJAX data-* атрибуты API (AJAX Data attributes API)",-1)),d(a),t[1]||(t[1]=u(`<p><a name="data-attributes" id="data-attributes" class="anchor"></a></p><h2 id="data-атрибуты-api"><a href="#data-атрибуты-api" class="header-anchor">#</a> data-* атрибуты API</h2><p>Data-* атрибуты позволяют Вам использовать AJAX без JavaScript. Вы пишете меньше кода, а получаете такой же результат. Список атрибутов:</p><div class="table"><table tabindex="0"><thead><tr><th>Атрибут</th><th>Описание</th></tr></thead><tbody><tr><td><strong>data-request</strong></td><td>имя AJAX обработчика.</td></tr><tr><td><strong>data-request-confirm</strong></td><td>сообщение с подтверждением. Окно показывается до того, как запрос будет отправлен. Если пользователь нажмет &quot;Отмена&quot;, то запрос не будет отправлен.</td></tr><tr><td><strong>data-request-redirect</strong></td><td>после того, как запрос будет успешно отправлен, пользователь перейдет на эту страницу.</td></tr><tr><td><strong>data-request-url</strong></td><td>URL, на который будет отправлен запрос. По умолчанию: <code>window.location.href</code></td></tr><tr><td><strong>data-request-update</strong></td><td>список фрагментов и элементов страницы (CSS селекторы), которые нужно обновить. Пример: <code>&#39;my-partial&#39;: &#39;#selector&#39;, &#39;partial&#39;: &#39;@#selector2&#39;, &#39;partial&#39;: &#39;^#selector2&#39;</code>. <code>@</code> - добавить результат перед содержимым элемента, <code>^</code> - после.</td></tr><tr><td><strong>data-request-data</strong></td><td>дополнительные параметры для передачи. Формат записи: <code>var: value, var: value</code>. При необходимости используйте кавычки: <code>myvar: &#39;some string&#39;</code>. Вы можете использовать данный атрибут на инициирующем элементе, например, на кнопке, на родительском элементе и на форме. Все атрибуты будут объединены в один массив. Если разные элементы будут иметь одинаковый атрибут, то в массив сохранится значение, которое ближе всего к инициирующему элементу.</td></tr><tr><td><strong>data-request-before-update</strong></td><td>JavaScript код, который необходимо выполнить до обновления содержимого элемента. Доступные переменные: <code>this</code>, <code>context</code>, <code>data</code>, <code>textStatus</code>,<code>jqXHR</code>.</td></tr><tr><td><strong>data-request-success</strong></td><td>JavaScript код, который необходимо выполнить после того, как запрос будет успешно завершен. Доступные переменные: <code>this</code>, <code>context</code>, <code>data</code>, <code>textStatus</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>data-request-error</strong></td><td>JavaScript код, который выполняется при возникновении ошибки. Доступные переменные: <code>this</code>, <code>context</code>, <code>textStatus</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>data-request-complete</strong></td><td>JavaScript код, который выполняется после окончания запроса. Доступные переменные: <code>this</code>, <code>context</code>, <code>textStatus</code>, <code>jqXHR</code>.</td></tr><tr><td><strong>data-request-loading</strong></td><td>CSS селектор элемента, который будет показан во время выполнения запроса. Вы можете использовать эту опцию для отображения индикатора загрузки. Эта функция использует jQuery функции <code>show()</code> и <code>hide()</code> для управления видимостью элемента.</td></tr><tr><td><strong>data-request-form</strong></td><td>CSS селектор формы, которая будет использоваться для получения данных. Если значение не указано, то используется ближайшая форма к инициирующему элементу.</td></tr><tr><td><strong>data-request-flash</strong></td><td>указывает серверу очистить и отправить <a href="./../ajax/extras.html#ajax-flash">флеш-сообщение</a> с полученым результатом.</td></tr><tr><td><strong>data-request-files</strong></td><td>разрешает загружать файлы.</td></tr><tr><td><strong>data-track-input</strong></td><td>применяется для тега <code>input</code> типа <code>text</code> или <code>password</code> и вызывает обработчик при изменении значения пользователем. Имеет необязательный параметр - время до отправления запроса (в миллисекундах).</td></tr></tbody></table></div><p>Атрибут <code>data-request</code> можно использовать в:</p><div class="table"><table tabindex="0"><thead><tr><th>Элемент</th><th>Событие</th></tr></thead><tbody><tr><td><strong>Форма</strong></td><td>при отправке.</td></tr><tr><td><strong>Ссылка, кнопка</strong></td><td>при нажатии.</td></tr><tr><td><strong>Поле типа <code>text</code>, <code>number</code> и <code>password</code></strong></td><td>когда изменяется значение и добавлен атрибут <code>data-track-input</code>.</td></tr><tr><td><strong>Select, checkboxes, radios</strong></td><td>когда выбран один из элементов.</td></tr></tbody></table></div><p><a name="data-attribute-examples" id="data-attribute-examples" class="anchor"></a></p><h2 id="примеры"><a href="#примеры" class="header-anchor">#</a> Примеры</h2><p>Использование обработчика <code>onCalculate</code> при отправке формы и обновлением элемента, имеющего идентификатор <code>&quot;result&quot;</code>, фрагментом <strong>calcresult</strong>:</p><pre><code>&lt;form data-request=&quot;onCalculate&quot; data-request-update=&quot;calcresult: &#39;#result&#39;&quot;&gt;
</code></pre><p>Вызов окна с подтверждением запроса:</p><pre><code>&lt;form ... &gt;
    ...
    &lt;button data-request=&quot;onDelete&quot; data-request-confirm=&quot;Are you sure?&quot;&gt;Delete&lt;/button&gt;
</code></pre><p>Перенаправление на другую страницу после успешного запроса:</p><pre><code>&lt;form data-request=&quot;onLogin&quot; data-request-redirect=&quot;/admin&quot;&gt;
</code></pre><p>Вызов окна после успешного запроса:</p><pre><code>&lt;form data-request=&quot;onLogin&quot; data-request-success=&quot;alert(&#39;Yay!&#39;)&quot;&gt;
</code></pre><p>Отправка параметра <code>mode</code> со значением <code>update</code>:</p><pre><code>&lt;form data-request=&quot;onUpdate&quot; data-request-data=&quot;mode: &#39;update&#39;&quot;&gt;
</code></pre><p>Отправка параметра <code>id</code> со значением <code>7</code>:</p><pre><code>&lt;div data-request-data=&quot;id: 7&quot;&gt;
    &lt;button data-request=&quot;onDelete&quot;&gt;Delete&lt;/button&gt;
    &lt;button data-request=&quot;onSave&quot;&gt;Update&lt;/button&gt;
&lt;/div&gt;
</code></pre><p><a href="./../services/request-input.html#files">Загрузка файлов</a>:</p><pre><code>&lt;form data-request=&quot;onSubmit&quot; data-request-files&gt;
    &lt;input type=&quot;file&quot; name=&quot;photo&quot; accept=&quot;image/*&quot; /&gt;
    &lt;button type=&quot;submit&quot;&gt;Submit&lt;/button&gt;
&lt;/form&gt;
</code></pre><p>15.02.2019</p>`,23))])}const x=r(l,[["render",p]]);export{f as __pageData,x as default};
